-- Each row reports orphan_count; all values should be zero before adding inferred FKs.
-- NULL child keys are ignored (SQL FK semantics).

SELECT 'business.country_fk -> country.id' AS relationship, count(*) AS orphan_count FROM public.business AS c LEFT JOIN public.country AS p ON c.country_fk = p.id WHERE c.country_fk IS NOT NULL AND p.id IS NULL;
